import React, { useEffect, useState } from "react";
import { useParams, useHistory } from "react-router-dom";
import { getCarById, UpdateCar } from "../../services/ApiCar";

export default function CardUpdateVoiture() {
  const { id } = useParams();
  const history = useHistory();
  const [car, setCar] = useState(null);
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const carburantOptions = ["Essence", "Diesel", "Hybride", "Électrique", "GPL", "Bioéthanol"];
  const transmissionOptions = ["Manuelle", "Automatique", "Semi-automatique"];
  const categorieOptions = ["Economique", "Compacte", "Berline", "SUV", "Monospace", "Sportive", "Luxe"];

  useEffect(() => {
    const fetchData = async () => {
      try {
        const data = await GetCarById(id);
        setCar(data);
      } catch (error) {
        console.error("Erreur de chargement:", error);
      }
    };

    fetchData();
  }, [id]);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setCar({
      ...car,
      [name]: type === "checkbox" ? checked : value,
    });

    if (errors[name]) {
      setErrors({ ...errors, [name]: "" });
    }
  };

  const validateForm = () => {
    const formErrors = {};
    const requiredFields = ["matricule", "model", "marque", "TypeDeCarburant", "prix", "prix_jour"];

    requiredFields.forEach((field) => {
      if (!car[field]) {
        formErrors[field] = `${field} est requis`;
      }
    });

    setErrors(formErrors);
    return Object.keys(formErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validateForm()) return;

    setIsSubmitting(true);

    try {
      await UpdateCar(id, car);
      history.push("/admin/Voiture");
    } catch (error) {
      console.error("Erreur de mise à jour:", error);
      alert(error.response?.data?.message || "Erreur lors de la mise à jour de la voiture");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (!car) return <div>Chargement...</div>;

  return (
    <div className="relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded-lg bg-blueGray-100 border-0">
      <div className="rounded-t bg-white mb-0 px-6 py-6">
        <div className="text-center flex justify-between">
          <h6 className="text-blueGray-700 text-xl font-bold">Modifier la voiture</h6>
          <button
            className="bg-lightBlue-500 text-white font-bold uppercase text-xs px-4 py-2 rounded shadow hover:shadow-md"
            type="button"
            onClick={() => history.push("/admin/Voiture")}
          >
            Retour
          </button>
        </div>
      </div>

      <div className="flex-auto px-4 lg:px-10 py-10 pt-0">
        <form onSubmit={handleSubmit}>
          <h6 className="text-blueGray-400 text-sm mt-3 mb-6 font-bold uppercase">
            Informations véhicule
          </h6>

          <div className="flex flex-wrap">
            {/* Matricule */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Matricule*</label>
                <input
                  type="text"
                  name="matricule"
                  value={car.matricule}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 bg-white rounded text-sm shadow w-full ${errors.matricule ? "border border-red-500" : ""}`}
                />
                {errors.matricule && <p className="text-red-500 text-xs italic mt-1">{errors.matricule}</p>}
              </div>
            </div>

            {/* Modèle */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Modèle*</label>
                <input
                  type="text"
                  name="model"
                  value={car.model}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 bg-white rounded text-sm shadow w-full ${errors.model ? "border border-red-500" : ""}`}
                />
                {errors.model && <p className="text-red-500 text-xs italic mt-1">{errors.model}</p>}
              </div>
            </div>

            {/* Marque */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Marque*</label>
                <input
                  type="text"
                  name="marque"
                  value={car.marque}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 bg-white rounded text-sm shadow w-full ${errors.marque ? "border border-red-500" : ""}`}
                />
                {errors.marque && <p className="text-red-500 text-xs italic mt-1">{errors.marque}</p>}
              </div>
            </div>

            {/* Carburant */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Carburant*</label>
                <select
                  name="TypeDeCarburant"
                  value={car.TypeDeCarburant}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 bg-white rounded text-sm shadow w-full ${errors.TypeDeCarburant ? "border border-red-500" : ""}`}
                >
                  <option value="">Sélectionner</option>
                  {carburantOptions.map((option) => (
                    <option key={option} value={option}>{option}</option>
                  ))}
                </select>
                {errors.TypeDeCarburant && <p className="text-red-500 text-xs italic mt-1">{errors.TypeDeCarburant}</p>}
              </div>
            </div>

            {/* Transmission */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Transmission</label>
                <select
                  name="Transmission"
                  value={car.Transmission}
                  onChange={handleChange}
                  className="border-0 px-3 py-3 bg-white rounded text-sm shadow w-full"
                >
                  <option value="">Sélectionner</option>
                  {transmissionOptions.map((option) => (
                    <option key={option} value={option}>{option}</option>
                  ))}
                </select>
              </div>
            </div>

            {/* Catégorie */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Catégorie</label>
                <select
                  name="Categorie"
                  value={car.Categorie}
                  onChange={handleChange}
                  className="border-0 px-3 py-3 bg-white rounded text-sm shadow w-full"
                >
                  <option value="">Sélectionner</option>
                  {categorieOptions.map((option) => (
                    <option key={option} value={option}>{option}</option>
                  ))}
                </select>
              </div>
            </div>

            {/* Nombre de sièges */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Nombre de sièges</label>
                <input
                  type="number"
                  name="NombreDeSiege"
                  value={car.NombreDeSiege}
                  onChange={handleChange}
                  min="2"
                  max="9"
                  className="border-0 px-3 py-3 bg-white rounded text-sm shadow w-full"
                />
              </div>
            </div>

            {/* Couleur */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Couleur</label>
                <input
                  type="text"
                  name="couleur"
                  value={car.couleur}
                  onChange={handleChange}
                  className="border-0 px-3 py-3 bg-white rounded text-sm shadow w-full"
                />
              </div>
            </div>
          </div>

          <hr className="mt-6 border-b-1 border-blueGray-300" />

          <h6 className="text-blueGray-400 text-sm mt-3 mb-6 font-bold uppercase">Tarification</h6>

          <div className="flex flex-wrap">
            <div className="w-full lg:w-6/12 px-4">
              <div className="mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Prix</label>
                <input
                  type="number"
                  name="prix"
                  value={car.prix}
                  onChange={handleChange}
                  min="0"
                  step="0.01"
                  className={`border-0 px-3 py-3 bg-white rounded text-sm shadow w-full ${errors.prix ? "border border-red-500" : ""}`}
                />
                {errors.prix && <p className="text-red-500 text-xs italic mt-1">{errors.prix}</p>}
              </div>
            </div>

            <div className="w-full lg:w-6/12 px-4">
              <div className="mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Prix par jour</label>
                <input
                  type="number"
                  name="prix_jour"
                  value={car.prix_jour}
                  onChange={handleChange}
                  min="0"
                  step="0.01"
                  className={`border-0 px-3 py-3 bg-white rounded text-sm shadow w-full ${errors.prix_jour ? "border border-red-500" : ""}`}
                />
                {errors.prix_jour && <p className="text-red-500 text-xs italic mt-1">{errors.prix_jour}</p>}
              </div>
            </div>
          </div>

          <hr className="mt-6 border-b-1 border-blueGray-300" />

          <div className="flex flex-wrap">
            {/* Disponible */}
            <div className="w-full lg:w-6/12 px-4">
              <label className="inline-flex items-center mt-3">
                <input
                  type="checkbox"
                  name="disponible"
                  checked={car.disponible}
                  onChange={handleChange}
                  className="form-checkbox h-5 w-5 text-lightBlue-600 rounded"
                />
                <span className="ml-2 text-blueGray-600 font-bold uppercase text-xs">
                  Disponible immédiatement
                </span>
              </label>
            </div>
          </div>

          <div className="text-center mt-6">
            <button
              type="submit"
              disabled={isSubmitting}
              className={`bg-lightBlue-500 text-white font-bold uppercase text-xs px-6 py-3 rounded shadow hover:shadow-md ${
                isSubmitting ? "opacity-50 cursor-not-allowed" : ""
              }`}
            >
              {isSubmitting ? "Mise à jour..." : "Mettre à jour"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
